  const assignedForObligation = key => domain.assignedOpenForInvoice(getObligation(key),db.assignments,db.attempts,db.confirmations,db.returns);
   const attemptableRemaining = assignmentId => {const a=db.assignments.find(x=>x.id===assignmentId);if(!a)return 0;const committed=db.attempts.filter(t=>t.assignmentId===a.id&&!['Fallido','Cancelado'].includes(t.state)).reduce((sum,t)=>sum+Math.max(0,Number(t.amount||0)-db.returns.filter(r=>r.attemptId===t.id).reduce((part,r)=>part+Number(r.amount||0),0)),0);return Math.max(0,Number(a.amount||0)-committed);};
  const assignmentRemaining = key => domain.assignmentAvailableForInvoice(getObligation(key),db.assignments,db.attempts,db.confirmations,db.returns);
