  const currentUser = () => currentRole.startsWith('Intermediario') ? currentRole.split('·')[1]?.trim() || 'Juan Salazar' : currentRole==='Aprobador' ? 'Paola Rivas' : currentRole==='Consulta / contabilidad' ? 'Elena Rojas' : currentRole==='Administrador de la empresa' ? 'Lucía Paredes' : 'Marco Salas';
