    missingConfirm().forEach(a=>rows.push({tone:'amber',title:'Sin confirmación del proveedor',detail:`${a.id} · evidencia ${a.state.toLowerCase()}; no cuenta como dinero recibido.`,date:a.date,attempt:a.id}));
