    movements.forEach(s=>{if(['Anticipo','Devolución'].includes(s.type)&&delivered.includes(s.state)){const sign=s.type==='Anticipo'?1:-1;advances[s.currency]=(advances[s.currency]||0)+sign*Number(s.amount||0);}if(s.type==='Reembolso'&&['Pendiente','Programada','Observada'].includes(s.state))refunds[s.currency]=(refunds[s.currency]||0)+Number(s.amount||0);if(['Comisión','Cargo'].includes(s.type)&&['Pendiente','Programada','Observada'].includes(s.state))fees[s.currency]=(fees[s.currency]||0)+Number(s.amount||0);});
