    const conf=Math.max(0,confirmedForObligation(o.id)); const pending=Math.max(0,o.amount-conf); const assigned=db.assignments.filter(a=>a.obligationId===o.id&&(!currentRole.startsWith('Intermediario')||a.intermediary===currentUser())); const ats=db.attempts.filter(a=>a.obligationId===o.id&&(!currentRole.startsWith('Intermediario')||a.intermediary===currentUser())); const rets=db.returns.filter(r=>ats.some(a=>a.id===r.attemptId)); const liquidations=db.settlements.filter(s=>s.obligationId===o.id&&(!currentRole.startsWith('Intermediario')||s.intermediary===currentUser()));
