    let nextText='El registro está conciliado.';let nextAction='';const returnedWithoutReceipt=conf===0&&rets.some(r=>!r.reducesProviderReceipt);const hasAdvanceForInvoice=db.settlements.some(s=>s.obligationId===o.id&&s.type==='Anticipo'&&domain.PAID_STATES.has(s.state));if(returnedWithoutReceipt){nextText=hasAdvanceForInvoice?'La transferencia se devolvió y el proveedor confirmó S/ 0. No registres recepción; revisa y regulariza el anticipo en el estado de cuenta.':'La transferencia se devolvió y el proveedor confirmó S/ 0. No registres recepción; asigna un nuevo pago si aún se debe al proveedor.';if(hasAdvanceForInvoice)nextAction=`<button class="button button-small" data-nav="liquidaciones">Revisar anticipo</button>`;else if(can('assign')&&assignmentRemaining(o.id)>0)nextAction=`<button class="button button-small button-primary" data-action="assignment" data-obligation="${esc(o.id)}">Asignar nuevo pago</button>`;}else if(!hasAssignment){nextText='Siguiente paso: asigna un importe a un intermediario.';if(can('assign'))nextAction=`<button class="button button-small button-primary" data-action="assignment" data-obligation="${esc(o.id)}">Asignar pago</button>`;}else if(!ats.length){nextText='Siguiente paso: el intermediario revisa la solicitud y registra el intento.';}else if(!hasEvidence){nextText='Siguiente paso: solicita o espera evidencia del intermediario.';}else if(!conf){nextText='Siguiente paso: confirma con el proveedor el importe recibido.';if(can('confirm'))nextAction=`<button class="button button-small button-primary" data-action="confirmation" data-attempt="${esc(ats.find(a=>a.hasProof)?.id||ats[0].id)}">Registrar confirmación</button>`;}else if(pending>0){nextText=`Recepción parcial. Quedan ${fmt(pending,o.currency)} por confirmar con el proveedor.`;}else if(!hasAbono){nextText='La factura está cubierta; revisa el estado de cuenta y registra el abono al intermediario si corresponde.';if(can('settle'))nextAction=`<button class="button button-small" data-action="settlement" data-obligation="${esc(o.id)}">Registrar abono</button>`;}else if(!reconciled){nextText='Revisa los movimientos y registra la conciliación final.';}
